ght:700;fill:#6366f1;font-family:'Rajdhani',monospace}.radar-diff-up[data-v-13064fe7]{font-size:9px;font-weight:700;fill:#059669;font-family:'Rajdhani',monospace}.radar-diff-down[data-v-13064fe7]{font-size:9px;font-weight:700;fill:#dc2626;font-family:'Rajdhani',monospace}.resonance-section[data-v-13064fe7]{background:#fffbeb;border:1px solid #fef3c7;border-radius:8px;padding:10px 12px;margin-bottom:10px}.resonance-header[data-v-13064fe7]{display:flex;align-items:center;gap:6px;margin-bottom:6px}.resonance-name[data-v-13064fe7]{font-size:13px;font-weight:700;color:#92400e;flex:1}.resonance-badge[data-v-13064fe7]{font-size:9px;font-weight:700;padding:1px 6px;border-radius:3px;background:#f1f5f9;color:#94a3b8}.resonance-badge.active[data-v-13064fe7]{background:#fef3c7;color:#d97706}.resonance-bar-track[data-v-13064fe7]{height:5px;background:#e8ecf1;border-radius:3px;overflow:hidden;margin-bottom:4px}.resonance-bar-fill[data-v-13064fe7]{height:100%;background:linear-gradient(90deg,#fbbf24,#f59e0b);border-radius:3px;transition:width 0.4s ease}.resonance-values[data-v-13064fe7]{display:flex;align-items:baseline;gap:2px}.resonance-current[data-v-13064fe7]{font-size:16px;font-weight:800;color:#f59e0b;font-family:'Rajdhani',monospace}.resonance-sep[data-v-13064fe7]{font-size:12px;color:#d1d5db}.resonance-max[data-v-13064fe7]{font-size:12px;color:#94a3b8;font-family:'Rajdhani',monospace}.mod-section[data-v-13064fe7]{margin-top:2px}.mod-title[data-v-13064fe7]{display:flex;align-items:center;gap:4px;font-size:11px;font-weight:700;color:#6366f1;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px}.mod-slots[data-v-13064fe7]{display:flex;gap:6px}.mod-slot[data-v-13064fe7]{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 6px;background:#fafbfe;border:1px solid #e8ecf1;border-radius:6px;min-height:52px;justify-content:center}.mod-slot.empty[data-v-13064fe7]{border-style:dashed;opacity:0.6}.mod-grade[data-v-13064fe7]{font-size:14px;font-wei