`, "",{"version":3,"sources":["webpack://./src/我的机娘是世界级的/脚本/状态栏/components/MechCard.vue"],"names":[],"mappings":"AAsOA,4BACE,eAAgB,CAChB,wBAAyB,CACzB,kBAAmB,CACnB,YAAa,CAEb,4FACF,CAGA,8BACE,kBAAmB,CACnB,mBAAoB,CACpB,+BACF,CAEA,gCACE,YAAa,CACb,kBAAmB,CACnB,6BAA8B,CAC9B,iBACF,CAEA,4BACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,kBAAmB,CACnB,2CACF,CAEA,8BACE,cAAe,CACf,eAAgB,CAChB,eAAgB,CAChB,iBAAkB,CAClB,wBAAyB,CACzB,oBACF,CAEA,4BACE,kBAAmB,CACnB,aAAc,CACd,wBACF,CAEA,8BACE,kBAAmB,CACnB,aAAc,CACd,wBACF,CAEA,iCACE,kBAAmB,CACnB,aAAc,CACd,wBACF,CAEA,4BACE,YAAa,CACb,OAAQ,CACR,kBACF,CAEA,iCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,0CACF,CAEA,gCACE,cAAe,CACf,aAAc,CACd,kBAAmB,CACnB,eAAgB,CAChB,iBACF,CAGA,gCACE,YAAa,CACb,sBAAuB,CACvB,YACF,CAEA,4BACE,WAAY,CACZ,YACF,CAEA,2BACE,YAAa,CACb,cAAe,CACf,gBACF,CAEA,6BACE,cAAe,CACf,gBACF,CAEA,kCACE,0BAA8B,CAC9B,cAAe,CACf,cAAe,CACf,oBACF,CAEA,6BACE,0BACF,CAEA,oCACE,SAAU,CACV,cAAe,CACf,cACF,CAEA,4BACE,YAAa,CACb,WAAY,CACZ,cACF,CAEA,8BACE,cAAe,CACf,eAAgB,CAChB,YACF,CAEA,8BACE,cAAe,CACf,eAAgB,CAChB,YAAa,CACb,gCACF,CAEA,gCACE,aAAc,CACd,eAAgB,CAChB,YAAa,CACb,gCACF,CAEA,kCACE,aAAc,CACd,eAAgB,CAChB,YAAa,CACb,gCACF,CAGA,oCACE,kBAAmB,CACnB,wBAAyB,CACzB,iBAAkB,CAClB,iBAAkB,CAClB,kBACF,CAEA,mCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,iBACF,CAEA,iCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,MACF,CAEA,kCACE,aAAc,CACd,eAAgB,CAChB,eAAgB,CAChB,iBAAkB,CAClB,kBAAmB,CACnB,aACF,CAEA,yCACE,kBAAmB,CACnB,aACF,CAEA,sCACE,UAAW,CACX,kBAAmB,CACnB,iBAAkB,CAClB,eAAgB,CAChB,iBACF,CAEA,qCACE,WAAY,CACZ,iDAAoD,CACpD,iBAAkB,CAClB,0BACF,CAEA,mCACE,YAAa,CACb,oBAAqB,CACrB,OACF,CAEA,oCACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,gCACF,CAEA,gCACE,cAAe,CACf,aACF,CAEA,gCACE,cAAe,CACf,aAAc,CACd,gCACF,CAGA,8BACE,cACF,CAEA,4BACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,iBAAkB,CAClB,wBAAyB,CACzB,oBACF,CAEA,4BACE,YAAa,CACb,OACF,CAEA,2BACE,MAAO,CACP,YAAa,CACb,qBAAsB,CACtB,kBAAmB,CACnB,OAAQ,CACR,eAAgB,CAChB,kBAAmB,CACnB,wBAAyB,CACzB,iBAAkB,CAClB,eAAgB,CAChB,sBACF,CAEA,iCACE,mBAAoB,CACpB,WACF,CAEA,4BACE,cAAe,CACf,eAAgB,CAChB,gCAAkC,CAClC,aACF,CAEA,0BAAW,aAAgB,CAC3B,0BAAW,aAAgB,CAC3B,0BAAW,aAAgB,CAC3B,0BAAW,aAAgB,CAC3B,0BAAW,aAAgB,CAC3B,0BAAW,aAAgB,CAE3B,2BACE,cAAe,CACf,eAAgB,CAChB,aAAc,CACd,iBAAkB,CAClB,eAAgB,CAChB,oBACF,CAEA,6BACE,aAAc,CACd,aAAc,CACd,eACF,CAEA,iCACE,aAAc,CACd,aACF,CAGA,yBACE,4BACE,YACF,CAEA,4BACE,WAAY,CACZ,YACF,CAEA,4BACE,cACF,CACF","sourcesContent":["<template>\n  <div class=\"mech-card\">\n    <!-- 顶部：机娘名 + 车型 -->\n    <div class=\"mech-header\">\n      <div class=\"mech-name-row\">\n        <span class=\"mech-name\">{{ name }}</span>\n        <span class=\"mech-status\" :class=\"statusClass\">{{ mech.状态 }}</span>\n      </div>\n      <div class=\"mech-meta\">\n        <span class=\"mech-car-model\">{{ mech._赛车型号 || '未知型号' }}</span>\n        <span v-if=\"mech._赛车类型\" class=\"mech-car-type\">{{ mech._赛车类型 }}</span>\n      </div>\n    </div>\n\n    <!-- 五维雷达图 -->\n    <div class=\"radar-section\">\n      <svg :viewBox=\"`0 0 ${svgSize} ${svgSize}`\" class=\"radar-svg\">\n        <!-- 背景环 -->\n        <polygon\n          v-for=\"level in [1, 0.75, 0.5, 0.25]\"\n          :key=\"level\"\n          :points=\"getPolygonPoints(level)\"\n          class=\"radar-bg\"\n          :style=\"{ opacity: 0.08 + level * 0.08 }\"\n        />\n        <!-- 轴线 -->\n        <line\n          v-for=\"(_, i) in DIMENSIONS\"\n          :key=\"'axis' + i\"\n          :x1=\"center\"\n          :y1=\"center\"\n          :x2=\"getPoint(i, 1).x\"\n          :y2=\"getPoint(i, 1).y\"\n          class=\"radar-axis\"\n        />\n        <!-- 基础数据区域 (半透明底色) -->\n        <polygon v-if=\"hasModDiff\" :points=\"baseDataPoints\" class=\"radar-data-base\" />\n        <!-- 最终数据区域 (实色) -->\n        <polygon :points=\"finalDataPoints\" class=\"radar-data\" />\n        <polygon :points=\"finalDataPoints\" class=\"radar-data-stroke\" />\n        <!-- 最终数据点 -->\n        <circle\n          v-for=\"(dim, i) in DIMENSIONS\"\n          :key=\"'dot' + i\"\n          :cx=\"getPoint(i, stats[dim].final / 100).x\"\n          :cy=\"getPoint(i, stats[dim].final / 100).y\"\n          r=\"4\"\n          class=\"radar-dot\"\n        />\n        <!-- 标签 -->\n        <text\n          v-for=\"(dim, i) in DIMENSIONS\"\n          :key=\"'label' + i\"\n          :x=\"getLabelPos(i).x\"\n          :y=\"getLabelPos(i).y\"\n          class=\"radar-label\"\n          text-anchor=\"middle\"\n          dominant-baseline=\"middle\"\n        >{{ dim }}</text>\n        <!-- 数值 (有改装加成时显示最终值+差值) -->\n        <text\n          v-for=\"(dim, i) in DIMENSIONS\"\n          :key=\"'val' + i\"\n          :x=\"getLabelPos(i).x\"\n          :y=\"getLabelPos(i).y + 13\"\n          class=\"radar-value\"\n          text-anchor=\"middle\"\n          dominant-baseline=\"middle\"\n        >{{ stats[dim].final }}</text>\n        <!-- 差值标记 -->\n        <text\n          v-for=\"(dim, i) in DIMENSIONS\"\n          :key=\"'diff' + i\"\n          v-show=\"stats[dim].diff !== 0\"\n          :x=\"getLabelPos(i).x\"\n          :y=\"getLabelPos(i).y + 24\"\n          :class=\"stats[dim].diff > 0 ? 'radar-diff-up' : 'radar-diff-down'\"\n          text-anchor=\"middle\"\n          dominant-baseline=\"middle\"\n        >{{ stats[dim].diff > 0 ? '+' : '' }}{{ stats[dim].diff }}</text>\n      </svg>\n    </div>\n\n    <!-- 共鸣技能 -->\n    <div class=\"resonance-section\">\n      <div class=\"resonance-header\">\n        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\">\n          <path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n        </svg>\n        <span class=\"resonance-name\">{{ mech.共鸣._技能名 }}</span>\n        <span class=\"resonance-badge\" :class=\"{ active: mech.共鸣._已激活 }\">\n          {{ mech.共鸣._已激活 ? '已激活' : '未激活' }}\n        </span>\n      </div>\n      <div class=\"resonance-bar-track\">\n        <div\n          class=\"resonance-bar-fill\"\n          :style=\"{ width: (mech.共鸣.当前共鸣值 / mech.共鸣._共鸣上限 * 100) + '%' }\"\n        ></div>\n      </div>\n      <div class=\"resonance-values\">\n        <span class=\"resonance-current\">{{ mech.共鸣.当前共鸣值 }}</span>\n        <span class=\"resonance-sep\">/</span>\n        <span class=\"resonance-max\">{{ mech.共鸣._共鸣上限 }}</span>\n      </div>\n    </div>\n\n    <!-- 改装插槽 -->\n    <div class=\"mod-section\">\n      <div class=\"mod-title\">\n        <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\">\n          <rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"3\" />\n          <path d=\"M8 2v20M16 2v20M2 8h20M2 16h20\" stroke-width=\"1\" opacity=\"0.4\" />\n        </svg>\n        <span>改装芯片</span>\n      </div>\n      <div class=\"mod-slots\">\n        <div\n          v-for=\"slot in ['槽位1', '槽位2', '槽位3']\"\n          :key=\"slot\"\n          class=\"mod-slot\"\n          :class=\"{ empty: !mech.改装插槽[slot as keyof typeof mech.改装插槽] }\"\n        >\n          <template v-if=\"mech.改装插槽[slot as keyof typeof mech.改装插槽]\">\n            <span class=\"mod-grade\" :class=\"'grade-' + mech.改装插槽[slot as keyof typeof mech.改装插槽]!.等级\">\n              {{ mech.改装插槽[slot as keyof typeof mech.改装插槽]!.等级 }}\n            </span>\n            <span class=\"mod-name\">{{ mech.改装插槽[slot as keyof typeof mech.改装插槽]!.名称 || '未命名' }}</span>\n            <span class=\"mod-effect\">\n              +{{ mech.改装插槽[slot as keyof typeof mech.改装插槽]!.增益值 }} {{ mech.改装插槽[slot as keyof typeof mech.改装插槽]!.增益维度 }}\n            </span>\n          </template>\n          <template v-else>\n            <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"1.5\">\n              <path d=\"M12 5v14M5 12h14\" stroke-linecap=\"round\" />\n            </svg>\n            <span class=\"mod-empty-text\">空槽位</span>\n          </template>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue';\nimport { DIMENSIONS, computeFinalStats, type DimensionKey, type FinalStats } from '../store';\n\nconst props = defineProps<{\n  name: string;\n  mech: {\n    _赛车型号: string;\n    _赛车类型: string;\n    状态: string;\n    五维: Record<DimensionKey, number>;\n    改装插槽: {\n      槽位1: { 名称: string; 等级: string; 增益维度: string; 增益值: number; 代价维度: string; 代价值: number } | null;\n      槽位2: { 名称: string; 等级: string; 增益维度: string; 增益值: number; 代价维度: string; 代价值: number } | null;\n      槽位3: { 名称: string; 等级: string; 增益维度: string; 增益值: number; 代价维度: string; 代价值: number } | null;\n    };\n    共鸣: {\n      技能名: string;\n      技能描述: string;\n      已激活: boolean;\n      当前共鸣值: number;\n      共鸣上限: number;\n    };\n  };\n  compact?: boolean;\n}>();\n\nconst statusClass = computed(() => {\n  if (props.mech.状态 === '正常') return 'status-ok';\n  if (props.mech.状态.includes('损伤') || props.mech.状态.includes('损坏')) return 'status-warn';\n  return 'status-default';\n});\n\n// 计算最终五维\nconst stats = computed<FinalStats>(() => computeFinalStats(props.mech));\n\n// 是否有改装差异（用于决定是否显示基础层）\nconst hasModDiff = computed(() => DIMENSIONS.some(dim => stats.value[dim].diff !== 0));\n\n// 雷达图参数\nconst svgSize = 220;\nconst center = svgSize / 2;\nconst radius = 78;\nconst labelOffset = 24;\n\nfunction getPoint(index: number, scale: number) {\n  const angle = (Math.PI * 2 * index) / DIMENSIONS.length - Math.PI / 2;\n  return {\n    x: center + radius * scale * Math.cos(angle),\n    y: center + radius * scale * Math.sin(angle),\n  };\n}\n\nfunction getPolygonPoints(scale: number) {\n  return DIMENSIONS.map((_, i) => {\n    const p = getPoint(i, scale);\n    return `${p.x},${p.y}`;\n  }).join(' ');\n}\n\nfunction getLabelPos(index: number) {\n  const angle = (Math.PI * 2 * index) / DIMENSIONS.length - Math.PI / 2;\n  return {\n    x: center + (radius + labelOffset) * Math.cos(angle),\n    y: center + (radius + labelOffset) * Math.sin(angle),\n  };\n}\n\n// 基础五维多边形\nconst baseDataPoints = computed(() => {\n  return DIMENSIONS.map((dim, i) => {\n    const p = getPoint(i, stats.value[dim].base / 100);\n    return `${p.x},${p.y}`;\n  }).join(' ');\n});\n\n// 最终五维多边形（含改装加成）\nconst finalDataPoints = computed(() => {\n  return DIMENSIONS.map((dim, i) => {\n    const p = getPoint(i, stats.value[dim].final / 100);\n    return `${p.x},${p.y}`;\n  }).join(' ');\n});\n</script>\n\n<style scoped>\n.mech-card {\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 10px;\n  padding: 14px;\n  /* 赛车风格斜切角 */\n  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));\n}\n\n/* 顶部 */\n.mech-header {\n  margin-bottom: 10px;\n  padding-bottom: 10px;\n  border-bottom: 2px solid #6366f1;\n}\n\n.mech-name-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 4px;\n}\n\n.mech-name {\n  font-size: 18px;\n  font-weight: 800;\n  color: #1e1b4b;\n  letter-spacing: 1px;\n  font-family: 'Rajdhani', system-ui, sans-serif;\n}\n\n.mech-status {\n  font-size: 10px;\n  font-weight: 700;\n  padding: 2px 8px;\n  border-radius: 4px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.status-ok {\n  background: #ecfdf5;\n  color: #059669;\n  border: 1px solid #a7f3d0;\n}\n\n.status-warn {\n  background: #fef3c7;\n  color: #d97706;\n  border: 1px solid #fcd34d;\n}\n\n.status-default {\n  background: #f1f5f9;\n  color: #64748b;\n  border: 1px solid #e2e8f0;\n}\n\n.mech-meta {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n\n.mech-car-model {\n  font-size: 12px;\n  font-weight: 600;\n  color: #6366f1;\n  font-family: 'Rajdhani', monospace, system-ui;\n}\n\n.mech-car-type {\n  font-size: 10px;\n  color: #94a3b8;\n  background: #f1f5f9;\n  padding: 1px 6px;\n  border-radius: 3px;\n}\n\n/* 雷达图 */\n.radar-section {\n  display: flex;\n  justify-content: center;\n  margin: 6px 0;\n}\n\n.radar-svg {\n  width: 220px;\n  height: 220px;\n}\n\n.radar-bg {\n  fill: #e8ecf1;\n  stroke: #d1d5db;\n  stroke-wi