ner-mini\">\n        <span class=\"partner-name\">{{ store.partnerMechName }}</span>\n        <span class=\"partner-model\">{{ store.partnerMech._赛车型号 }}</span>\n        <span class=\"partner-status\" :class=\"store.partnerMech.状态 === '正常' ? 'ok' : 'warn'\">\n          {{ store.partnerMech.状态 }}\n        </span>\n      </div>\n      <div class=\"partner-resonance\">\n        <span class=\"res-label\">共鸣</span>\n        <div class=\"res-bar-track\">\n          <div class=\"res-bar-fill\" :style=\"{ width: (store.partnerMech.共鸣.当前共鸣值 / store.partnerMech.共鸣._共鸣上限 * 100) + '%' }\"></div>\n        </div>\n        <span class=\"res-val\">{{ store.partnerMech.共鸣.当前共鸣值 }}/{{ store.partnerMech.共鸣._共鸣上限 }}</span>\n      </div>\n    </div>\n    <div v-else class=\"no-partner\">\n      <span>未指定搭档机娘</span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useStatusStore } from '../store';\nconst store = useStatusStore();\n</script>\n\n<style scoped>\n.tab-pre-battle {\n  padding: 12px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n/* 赛事信息 */\n.race-info-card {\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 10px;\n  overflow: hidden;\n  margin-bottom: 12px;\n  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));\n}\n\n.race-banner {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  background: linear-gradient(135deg, #fef3c7, #fffbeb);\n  border-bottom: 2px solid #f59e0b;\n}\n\n.race-name {\n  font-size: 15px;\n  font-weight: 800;\n  color: #92400e;\n  letter-spacing: 0.5px;\n  font-family: 'Rajdhani', system-ui;\n}\n\n.race-details {\n  display: flex;\n  gap: 0;\n  padding: 0;\n}\n\n.race-detail-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: 10px 8px;\n  border-right: 1px solid #f1f5f9;\n}\n\n.race-detail-item:last-child {\n  border-right: none;\n}\n\n.detail-label {\n  font-size: 10px;\n  color: #94a3b8;\n  font-weight: 500;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.detail-value {\n  font-size: 15px;\n  font-weight: 800;\n  color: #374151;\n  font-family: 'Rajdhani', monospace;\n}\n\n.detail-value.tier {\n  color: #6366f1;\n}\n\n.no-race {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  padding: 32px 20px;\n  color: #cbd5e1;\n  font-size: 13px;\n}\n\n/* 信用点 */\n.credits-bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  background: #fffbeb;\n  border: 1px solid #fef3c7;\n  border-radius: 8px;\n  margin-bottom: 12px;\n}\n\n.credits-label {\n  font-size: 12px;\n  color: #92400e;\n  flex: 1;\n}\n\n.credits-value {\n  font-size: 18px;\n  font-weight: 900;\n  color: #f59e0b;\n  font-family: 'Rajdhani', monospace;\n}\n\n/* 搭档快览 */\n.partner-preview {\n  background: #fafbfe;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n  padding: 12px;\n}\n\n.partner-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  font-weight: 700;\n  color: #374151;\n  margin-bottom: 8px;\n}\n\n.partner-mini {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.partner-name {\n  font-size: 14px;\n  font-weight: 800;\n  color: #1e1b4b;\n}\n\n.partner-model {\n  font-size: 11px;\n  color: #94a3b8;\n  font-family: 'Rajdhani', monospace;\n  flex: 1;\n}\n\n.partner-status {\n  font-size: 9px;\n  font-weight: 700;\n  padding: 1px 6px;\n  border-radius: 3px;\n}\n\n.partner-status.ok {\n  background: #ecfdf5;\n  color: #059669;\n}\n\n.partner-status.warn {\n  background: #fef3c7;\n  color: #d97706;\n}\n\n.partner-resonance {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.res-label {\n  font-size: 10px;\n  color: #94a3b8;\n  width: 28px;\n}\n\n.res-bar-track {\n  flex: 1;\n  height: 5px;\n  background: #e8ecf1;\n  border-radius: 3px;\n  overflow: hidden;\n}\n\n.res-bar-fill {\n  height: 100%;\n  background: linear-gradient(90deg, #fbbf24, #f59e0b);\n  border-radius: 3px;\n  transition: width 0.4s;\n}\n\n.res-val {\n  font-size: 11px;\n  font-weight: 700;\n  color: #f59e0b;\n  font-family: 'Rajdhani', monospace;\n  min-width: 45px;\n  text-align: right;\n}\n\n.no-partner {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n  color: #cbd5e1;\n  font-size: 12px;\n}\n</style>\n"],"sourceRoot":""}]);
