row\"\n      >\n        <div class=\"opp-rank\" :class=\"getRankClass(opponent.当前排名)\">\n          {{ opponent.当前排名 || '--' }}\n        </div>\n        <div class=\"opp-info\">\n          <div class=\"opp-driver\">{{ opponent.车手名 || name }}</div>\n          <div class=\"opp-mech\">{{ opponent.机娘名 }}</div>\n        </div>\n        <div class=\"opp-skill\">\n          <span class=\"opp-skill-name\">{{ opponent.共鸣技能 }}</span>\n          <span class=\"opp-skill-status\" :class=\"{ used: opponent.技能已使用 }\">\n            {{ opponent.技能已使用 ? 'USED' : 'HOLD' }}\n          </span>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue';\nimport { useStatusStore } from '../store';\n\nconst store = useStatusStore();\n\nconst opponentCount = computed(() => Object.keys(store.data.当前比赛.对手).length);\n\nfunction getRankClass(rank: number) {\n  if (rank === 1) return 'rank-1';\n  if (rank === 2) return 'rank-2';\n  if (rank === 3) return 'rank-3';\n  return '';\n}\n</script>\n\n<style scoped>\n.tab-opponents {\n  padding: 12px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n.opponents-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  font-weight: 700;\n  color: #1e1b4b;\n  margin-bottom: 10px;\n  padding-bottom: 8px;\n  border-bottom: 2px solid #ef4444;\n}\n\n.opponent-count {\n  margin-left: auto;\n  font-size: 10px;\n  font-weight: 600;\n  color: #94a3b8;\n  background: #f1f5f9;\n  padding: 1px 8px;\n  border-radius: 4px;\n}\n\n.empty-state {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 32px 20px;\n  color: #cbd5e1;\n  font-size: 13px;\n}\n\n.opponents-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.opponent-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  background: #fff;\n  border: 1px solid #f1f5f9;\n  border-radius: 6px;\n  transition: background 0.2s;\n}\n\n.opponent-row:hover {\n  background: #fafbfe;\n}\n\n.opp-rank {\n  width: 32px;\n  height: 32px;\n  border-radius: 6px;\n  background: #f1f5f9;\n  color: #64748b;\n  font-size: 14px;\n  font-weight: 900;\n  font-family: 'Rajdhani', monospace;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.opp-rank.rank-1 {\n  background: #fef3c7;\n  color: #d97706;\n}\n\n.opp-rank.rank-2 {\n  background: #f1f5f9;\n  color: #94a3b8;\n}\n\n.opp-rank.rank-3 {\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.opp-info {\n  flex: 1;\n  min-width: 0;\n}\n\n.opp-driver {\n  font-size: 12px;\n  font-weight: 700;\n  color: #374151;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.opp-mech {\n  font-size: 10px;\n  color: #94a3b8;\n}\n\n.opp-skill {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 2px;\n  flex-shrink: 0;\n}\n\n.opp-skill-name {\n  font-size: 10px;\n  font-weight: 600;\n  color: #6366f1;\n}\n\n.opp-skill-status {\n  font-size: 8px;\n  font-weight: 800;\n  padding: 1px 5px;\n  border-radius: 3px;\n  background: #ecfdf5;\n  color: #059669;\n  letter-spacing: 0.5px;\n}\n\n.opp-skill-status.used {\n  background: #f1f5f9;\n  color: #94a3b8;\n  text-decoration: line-through;\n}\n</style>\n"],"sourceRoot":""}]);
