\">\n      <div class=\"banner-left\">\n        <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\">\n          <path d=\"M3 6a3 3 0 013-3h10a1 1 0 01.8 1.6L14.25 8l2.55 3.4A1 1 0 0116 13H6a1 1 0 00-1 1v3a1 1 0 11-2 0V6z\" />\n        </svg>\n        <div>\n          <div class=\"race-name\">{{ store.data.当前比赛._赛事名称 || 'RACE' }}</div>\n          <div class=\"race-type\">{{ store.data.当前比赛._赛事类型 || '' }} · {{ store.data.当前比赛._赛事级别 || '' }}</div>\n        </div>\n      </div>\n      <div class=\"race-track-status\" v-if=\"store.data.当前比赛.赛道状态\">\n        {{ store.data.当前比赛.赛道状态 }}\n      </div>\n    </div>\n\n    <!-- 核心赛况：排名 + 圈数 -->\n    <div class=\"race-core\">\n      <div class=\"rank-display\">\n        <span class=\"rank-label\">RANK</span>\n        <span class=\"rank-number\">{{ store.data.当前比赛.当前排名 || '--' }}</span>\n      </div>\n      <div class=\"lap-display\">\n        <span class=\"lap-label\">LAP</span>\n        <div class=\"lap-progress\">\n          <div class=\"lap-bar-track\">\n            <div\n              class=\"lap-bar-fill\"\n              :style=\"{ width: lapPercent + '%' }\"\n            ></div>\n          </div>\n          <span class=\"lap-text\">{{ store.data.当前比赛.当前圈数 }} / {{ store.data.当前比赛.总圈数 }}</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- 搭档机娘迷你状态 -->\n    <div class=\"partner-mini-bar\" v-if=\"store.partnerMechName && store.partnerMech\">\n      <div class=\"mini-header\">\n        <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"2\">\n          <path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n        </svg>\n        <span class=\"mini-name\">{{ store.partnerMechName }}</span>\n        <span class=\"mini-status\" :class=\"store.partnerMech.状态 === '正常' ? 'ok' : 'warn'\">\n          {{ store.partnerMech.状态 }}\n        </span>\n      </div>\n      <div class=\"mini-bars\">\n        <div class=\"mini-bar-row\">\n          <span class=\"bar-label\">共鸣</span>\n          <div class=\"bar-track\">\n            <div class=\"bar-fill resonance\" :style=\"{ width: resonancePercent + '%' }\"></div>\n          </div>\n          <span class=\"bar-val\">{{ store.partnerMech.共鸣.当前共鸣值 }}</span>\n        </div>\n        <div class=\"mini-bar-row\">\n          <span class=\"bar-label\">耐久</span>\n          <div class=\"bar-track\">\n            <div class=\"bar-fill endurance\" :style=\"{ width: store.partnerMech.五维.耐久 + '%' }\"></div>\n          </div>\n          <span class=\"bar-val\">{{ store.partnerMech.五维.耐久 }}</span>\n        </div>\n      </div>\n      <div class=\"skill-status\">\n        <svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\">\n          <path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n        </svg>\n        <span>{{ store.partnerMech.共鸣._技能名 }}</span>\n        <span class=\"skill-badge\" :class=\"{ ready: store.partnerMech.共鸣._已激活 }\">\n          {{ store.partnerMech.共鸣._已激活 ? 'READY' : 'LOCKED' }}\n        </span>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue';\nimport { useStatusStore } from '../store';\n\nconst store = useStatusStore();\n\nconst lapPercent = computed(() => {\n  const total = store.data.当前比赛.总圈数;\n  if (total <= 0) return 0;\n  return Math.min((store.data.当前比赛.当前圈数 / total) * 100, 100);\n});\n\nconst resonancePercent = computed(() => {\n  if (!store.partnerMech) return 0;\n  const max = store.partnerMech.共鸣._共鸣上限;\n  if (max <= 0) return 0;\n  return (store.partnerMech.共鸣.当前共鸣值 / max) * 100;\n});\n</script>\n\n<style scoped>\n.tab-race {\n  padding: 12px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n/* 赛事横幅 */\n.race-banner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 10px 14px;\n  background: linear-gradient(135deg, #fef2f2, #fff1f2);\n  border: 1px solid #fecaca;\n  border-radius: 8px;\n  margin-bottom: 12px;\n  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));\n}\n\n.banner-left {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.race-name {\n  font-size: 15px;\n  font-weight: 900;\n  color: #991b1b;\n  letter-spacing: 0.5px;\n  font-family: 'Rajdhani', system-ui;\n}\n\n.race-type {\n  font-size: 10px;\n  color: #dc2626;\n  font-weight: 500;\n}\n\n.race-track-status {\n  font-size: 10px;\n  font-weight: 700;\n  padding: 2px 8px;\n  border-radius: 4px;\n  background: #fef3c7;\n  color: #92400e;\n}\n\n/* 核心赛况 */\n.race-core {\n  display: flex;\n  gap: 12px;\n  margin-bottom: 12px;\n}\n\n.rank-display {\n  width: 90px;\n  padding: 12px;\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n  text-align: center;\n  flex-shrink: 0;\n  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);\n}\n\n.rank-label {\n  font-size: 9px;\n  font-weight: 700;\n  color: #94a3b8;\n  letter-spacing: 2px;\n  display: block;\n  margin-bottom: 2px;\n}\n\n.rank-number {\n  font-size: 36px;\n  font-weight: 900;\n  color: #ef4444;\n  font-family: 'Rajdhani', monospace;\n  line-height: 1;\n}\n\n.lap-display {\n  flex: 1;\n  padding: 12px;\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n}\n\n.lap-label {\n  font-size: 9px;\n  font-weight: 700;\n  color: #94a3b8;\n  letter-spacing: 2px;\n  display: block;\n  margin-bottom: 6px;\n}\n\n.lap-progress {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.lap-bar-track {\n  height: 8px;\n  background: #e8ecf1;\n  border-radius: 4px;\n  overflow: hidden;\n}\n\n.lap-bar-fill {\n  height: 100%;\n  background: linear-gradient(90deg, #6366f1, #8b5cf6);\n  border-radius: 4px;\n  transition: width 0.5s ease;\n}\n\n.lap-text {\n  font-size: 18px;\n  font-weight: 900;\n  color: #1e1b4b;\n  font-family: 'Rajdhani', monospace;\n}\n\n/* 搭档迷你条 */\n.partner-mini-bar {\n  background: #fafbfe;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n  padding: 10px 12px;\n}\n\n.mini-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 8px;\n}\n\n.mini-name {\n  font-size: 13px;\n  font-weight: 800;\n  color: #1e1b4b;\n  flex: 1;\n}\n\n.mini-status {\n  font-size: 9px;\n  font-weight: 700;\n  padding: 1px 6px;\n  border-radius: 3px;\n}\n\n.mini-status.ok { background: #ecfdf5; color: #059669; }\n.mini-status.warn { background: #fef3c7; color: #d97706; }\n\n.mini-bars {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin-bottom: 8px;\n}\n\n.mini-bar-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.bar-label {\n  font-size: 10px;\n  color: #94a3b8;\n  width: 28px;\n  font-weight: 600;\n}\n\n.bar-track {\n  flex: 1;\n  height: 5px;\n  background: #e8ecf1;\n  border-radius: 3px;\n  overflow: hidden;\n}\n\n.bar-fill {\n  height: 100%;\n  border-radius: 3px;\n  transition: width 0.4s;\n}\n\n.bar-fill.resonance {\n  background: linear-gradient(90deg, #fbbf24, #f59e0b);\n}\n\n.bar-fill.endurance {\n  background: linear-gradient(90deg, #6ee7b7, #10b981);\n}\n\n.bar-val {\n  font-size: 11px;\n  font-weight: 700;\n  color: #374151;\n  font-family: 'Rajdhani', monospace;\n  width: 28px;\n  text-align: right;\n}\n\n/* 技能状态 */\n.skill-status {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 11px;\n  font-weight: 600;\n  color: #92400e;\n}\n\n.skill-badge {\n  font-size: 9px;\n  font-weight: 800;\n  padding: 1px 6px;\n  border-radius: 3px;\n  background: #f1f5f9;\n  color: #94a3b8;\n  letter-spacing: 0.5px;\n  margin-left: auto;\n}\n\n.skill-badge.ready {\n  background: #fef3c7;\n  color: #d97706;\n}\n</style>\n"],"sourceRoot":""}]);
