,CAClB,YAAa,CACb,0BACF,CAEA,gCACE,iBAAkB,CAClB,KAAM,CACN,WAAY,CACZ,kBAAmB,CACnB,yBAA0B,CAC1B,wBACF,CAEA,gCACE,iBAAkB,CAClB,KAAM,CACN,WAAY,CACZ,kBAAmB,CACnB,WAAY,CACZ,iBAAkB,CAClB,wBACF,CAEA,kDACE,YACF,CAEA,oDACE,YACF,CAGA,8BACE,YAAa,CACb,qBAAsB,CACtB,kBAAmB,CACnB,sBAAuB,CACvB,QAAS,CACT,iBAAkB,CAClB,aAAc,CACd,cACF","sourcesContent":["<template>\n  <div class=\"tab-mod\">\n    <!-- 有目标机娘 -->\n    <template v-if=\"targetName && targetMech\">\n      <!-- 标题 -->\n      <div class=\"mod-header\">\n        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\">\n          <rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"3\" />\n          <path d=\"M8 2v20M16 2v20M2 8h20M2 16h20\" stroke-width=\"1\" opacity=\"0.4\" />\n        </svg>\n        <span>{{ targetName }} - 改装面板</span>\n        <span v-if=\"!store.canModify\" class=\"readonly-badge\">只读</span>\n      </div>\n\n      <!-- 三个槽位 -->\n      <div class=\"slots-section\">\n        <div class=\"section-label\">装备槽位</div>\n        <div class=\"slots-list\">\n          <div\n            v-for=\"(slotKey, index) in slotKeys\"\n            :key=\"slotKey\"\n            class=\"slot-card\"\n            :class=\"{\n              empty: !targetMech.改装插槽[slotKey],\n              active: activeSlot === slotKey,\n              clickable: store.canModify,\n            }\"\n            @click=\"onSlotClick(slotKey)\"\n          >\n            <div class=\"slot-index\">{{ index + 1 }}</div>\n\n            <template v-if=\"targetMech.改装插槽[slotKey]\">\n              <div class=\"slot-info\">\n                <div class=\"slot-top\">\n                  <span class=\"slot-grade\" :class=\"'grade-' + targetMech.改装插槽[slotKey]!.等级\">\n                    {{ targetMech.改装插槽[slotKey]!.等级 }}级\n                  </span>\n                  <span class=\"slot-name\">{{ targetMech.改装插槽[slotKey]!.名称 || '未命名芯片' }}</span>\n                </div>\n                <div class=\"slot-effects\">\n                  <span class=\"effect-plus\">\n                    <svg viewBox=\"0 0 16 16\" width=\"10\" height=\"10\">\n                      <path d=\"M8 3v10M3 8h10\" stroke=\"#10b981\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" />\n                    </svg>\n                    {{ targetMech.改装插槽[slotKey]!.增益维度 }} +{{ targetMech.改装插槽[slotKey]!.增益值 }}\n                  </span>\n                  <span v-if=\"targetMech.改装插槽[slotKey]!.代价值 > 0\" class=\"effect-minus\">\n                    <svg viewBox=\"0 0 16 16\" width=\"10\" height=\"10\">\n                      <path d=\"M3 8h10\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" />\n                    </svg>\n                    {{ targetMech.改装插槽[slotKey]!.代价维度 }} -{{ targetMech.改装插槽[slotKey]!.代价值 }}\n                  </span>\n                </div>\n              </div>\n              <!-- 拆卸按钮 -->\n              <button v-if=\"store.canModify\" class=\"uninstall-btn\" title=\"拆卸\" @click.stop=\"handleUninstall(slotKey)\">\n                <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n                  <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n                  <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n                </svg>\n              </button>\n            </template>\n\n            <template v-else>\n              <div class=\"slot-empty\">\n                <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#d1d5db\" stroke-width=\"1.5\">\n                  <path d=\"M12 5v14M5 12h14\" stroke-linecap=\"round\" />\n                </svg>\n                <span>{{ store.canModify ? '点击选择改件安装' : '空槽位' }}</span>\n              </div>\n            </template>\n\n            <!-- 选中指示器 -->\n            <div v-if=\"activeSlot === slotKey && store.canModify\" class=\"slot-active-indicator\">\n              <svg viewBox=\"0 0 16 16\" width=\"12\" height=\"12\">\n                <path d=\"M8 2l6 12H2z\" fill=\"#6366f1\" />\n              </svg>\n            </div>\n          </div>\n\n          <!-- 展开的仓库列表（在选中的槽位下方） -->\n          <Transition name=\"slide\">\n            <div\n              v-if=\"activeSlot && store.canModify\"\n              :key=\"activeSlot\"\n              class=\"inline-warehouse\"\n            >\n              <div class=\"iw-header\">\n                <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\">\n                  <path d=\"M20 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2Z\" />\n                  <path d=\"M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2\" />\n                </svg>\n                <span>选择改件安装到 槽位{{ activeSlot.replace('槽位', '') }}</span>\n                <button class=\"iw-close\" @click.stop=\"activeSlot = null\">\n                  <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n                    <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n                    <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n                  </svg>\n                </button>\n              </div>\n\n              <div v-if=\"store.warehouse.length === 0\" class=\"iw-empty\">\n                <svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"1.5\">\n                  <rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"3\" />\n                  <path d=\"M8 12h8\" stroke-linecap=\"round\" />\n                </svg>\n                <span>仓库中没有改件</span>\n              </div>\n\n              <div v-else class=\"iw-list\">\n                <div\n                  v-for=\"(mod, idx) in store.warehouse\"\n                  :key=\"idx\"\n                  class=\"iw-item\"\n                  @click.stop=\"handleInstall(idx)\"\n                >\n                  <div class=\"iw-item-grade\" :class=\"'grade-' + mod.等级\">{{ mod.等级 }}</div>\n                  <div class=\"iw-item-info\">\n                    <div class=\"iw-item-name\">{{ mod.名称 || '未命名' }}</div>\n                    <div class=\"iw-item-effect\">\n                      <span class=\"effect-plus-sm\">{{ mod.增益维度 }}+{{ mod.增益值 }}</span>\n                      <span v-if=\"mod.代价值 > 0\" class=\"effect-minus-sm\">{{ mod.代价维度 }}-{{ mod.代价值 }}</span>\n                    </div>\n                  </div>\n                  <div class=\"iw-item-action\">\n                    <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\" stroke-linecap=\"round\">\n                      <path d=\"M12 5v14M5 12h14\" />\n                    </svg>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </Transition>\n        </div>\n      </div>\n\n      <!-- 最终五维对比面板 -->\n      <div class=\"final-stats-section\">\n        <div class=\"section-label\">\n          <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"2\">\n            <polygon points=\"12,2 22,8.5 22,15.5 12,22 2,15.5 2,8.5\" />\n            <polygon points=\"12,6 18,9.5 18,14.5 12,18 6,14.5 6,9.5\" opacity=\"0.3\" />\n          </svg>\n          最终五维\n          <span class=\"stats-hint\">基础 + 改装加成</span>\n        </div>\n        <div class=\"stats-grid\">\n          <div\n            v-for=\"dim in DIMENSIONS\"\n            :key=\"dim\"\n            class=\"stat-row\"\n            :class=\"{\n              'stat-up': finalStats[dim].diff > 0,\n              'stat-down': finalStats[dim].diff < 0,\n            }\"\n          >\n            <span class=\"stat-dim\">\n              <span class=\"stat-abbr\">{{ DIM_ABBR[dim] }}</span>\n              {{ dim }}\n            </span>\n            <span class=\"stat-values\">\n              <span class=\"stat-base\">{{ finalStats[dim].base }}</span>\n              <svg v-if=\"finalStats[dim].diff !== 0\" viewBox=\"0 0 16 16\" width=\"12\" height=\"12\" class=\"stat-arrow\">\n                <path d=\"M4 8h8M9 5l3 3-3 3\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" />\n              </svg>\n              <span v-if=\"finalStats[dim].diff === 0\" class=\"stat-eq\">=</span>\n              <span class=\"stat-final\" :class=\"{ 'val-up': finalStats[dim].diff > 0, 'val-down': finalStats[dim].diff < 0 }\">\n                {{ finalStats[dim].final }}\n              </span>\n              <span v-if=\"finalStats[dim].diff !== 0\" class=\"stat-diff\" :class=\"{ 'diff-up': finalStats[dim].diff > 0, 'diff-down': finalStats[dim].diff < 0 }\">\n                {{ finalStats[dim].diff > 0 ? '+' : '' }}{{ finalStats[dim].diff }}\n              </span>\n            </span>\n            <!-- 进度条 -->\n            <div class=\"stat-bar-track\">\n              <div class=\"stat-bar-base\" :style=\"{ width: finalStats[dim].base + '%' }\"></div>\n              <div\n                v-if=\"finalStats[dim].diff > 0\"\n                class=\"stat-bar-gain\"\n                :style=\"{ left: finalStats[dim].base + '%', width: finalStats[dim].diff + '%' }\"\n              ></div>\n              <div\n                v-if=\"finalStats[dim].diff < 0\"\n                class=\"stat-bar-loss\"\n                :style=\"{ left: finalStats[dim].final + '%', width: Math.abs(finalStats[dim].diff) + '%' }\"\n              ></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 赛事改件限制提示 -->\n      <div class=\"mod-notice\">\n        <svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\">\n          <circle cx=\"12\" cy=\"12\" r=\"10\" />\n          <path d=\"M12 8v4M12 16h.01\" stroke-linecap=\"round\" />\n        </svg>\n        <span>\n          当前赛事级别 {{ store.data.当前比赛._赛事级别 || store.data.主角._赛事等级 }}，\n          改件等级须符合赛事规定\n        </span>\n      </div>\n    </template>\n\n    <!-- 没有目标机娘 -->\n    <div v-else class=\"empty-state\">\n      <svg viewBox=\"0 0 24 24\" width=\"36\" height=\"36\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"1.5\">\n        <rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"3\" />\n        <path d=\"M12 8v8M8 12h8\" stroke-linecap=\"round\" />\n      </svg>\n      <span v-if=\"store.gameState === '日常'\">请先在「机娘库」中选择一位机娘</span>\n      <span v-else>未指定搭档机娘，无法查看改装</span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useStatusStore, DIMENSIONS, DIM_ABBR, computeFinalStats, type FinalStats } from '../store';\n\nconst store = useStatusStore();\n\nconst slotKeys = ['槽位1', '槽位2', '槽位3'] as const;\ntype SlotKey = (typeof slotKeys)[number];\n\n// 目标机娘\nconst targetName = computed(() => store.modTargetName);\nconst targetMech = computed(() => store.modTargetMech);\n\n// 当前展开的槽位\nconst activeSlot = ref<SlotKey | null>(null);\n\n// 最终五维\nconst defaultStats: FinalStats = DIMENSIONS.reduce((acc, dim) => {\n  acc[dim] = { base: 0, final: 0, diff: 0 };\n  return acc;\n}, {} as FinalStats);\n\nconst finalStats = computed<FinalStats>(() => {\n  if (!targetMech.value) return defaultStats;\n  return computeFinalStats(targetMech.value);\n});\n\n// 点击槽位：展开/收起仓库列表\nfunction onSlotClick(slotKey: SlotKey) {\n  if (!store.canModify) return;\n  // 切换选中状态\n  activeSlot.value = activeSlot.value === slotKey ? null : slotKey;\n}\n\n// 从仓库安装改件到当前选中的槽位\nasync function handleInstall(warehouseIndex: number) {\n  if (!activeSlot.value) return;\n  await store.installMod(warehouseIndex, activeSlot.value);\n  activeSlot.value = null; // 安装后收起仓库\n}\n\n// 拆卸改件\nasync function handleUninstall(slotKey: SlotKey) {\n  await store.uninstallMod(slotKey);\n  // 如果拆卸的是当前展开的槽位，保持展开以便安装新的\n}\n</script>\n\n<style scoped>\n.tab-mod {\n  padding: 12px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n.mod-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  font-weight: 700;\n  color: #1e1b4b;\n  margin-bottom: 12px;\n  padding-bottom: 8px;\n  border-bottom: 2px solid #6366f1;\n}\n\n.readonly-badge {\n  font-size: 10px;\n  font-weight: 600;\n  padding: 1px 6px;\n  border-radius: 3px;\n  background: #f1f5f9;\n  color: #94a3b8;\n  margin-left: auto;\n}\n\n.section-label {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 12px;\n  font-weight: 700;\n  color: #475569;\n  margin-bottom: 8px;\n}\n\n/* ─── 槽位 ─── */\n.slots-section {\n  margin-bottom: 14px;\n}\n\n.slots-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.slot-card {\n  display: flex;\n  gap: 10px;\n  padding: 12px;\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n  align-items: center;\n  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));\n  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;\n  position: relative;\n}\n\n.slot-card.clickable {\n  cursor: pointer;\n}\n\n.slot-card.clickable:hover {\n  border-color: #c7d2fe;\n  background: #fafaff;\n}\n\n.slot-card.empty {\n  border-style: dashed;\n  opacity: 0.7;\n}\n\n.slot-card.empty.clickable:hover {\n  opacity: 1;\n  border-color: #6366f1;\n  background: #f5f3ff;\n}\n\n.slot-card.active {\n  border-color: #6366f1;\n  background: #f5f3ff;\n  border-style: solid;\n  opacity: 1;\n  box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.15);\n}\n\n.slot-active-indicator {\n  position: absolute;\n  bottom: -6px;\n  left: 50%;\n  transform: translateX(-50%) rotate(180deg);\n  z-index: 1;\n}\n\n.slot-index {\n  width: 28px;\n  height: 28px;\n  border-radius: 6px;\n  background: #6366f1;\n  color: #fff;\n  font-size: 13px;\n  font-weight: 800;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  font-family: 'Rajdhani', monospace;\n}\n\n.slot-info {\n  flex: 1;\n  min-width: 0;\n}\n\n.slot-top {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 4px;\n}\n\n.slot-grade {\n  font-size: 12px;\n  font-weight: 900;\n  font-family: 'Rajdhani', monospace;\n  padding: 1px 6px;\n  border-radius: 3px;\n}\n\n.grade-S { color: #f59e0b; background: #fef3c7; }\n.grade-A { color: #ef4444; background: #fef2f2; }\n.grade-B { color: #8b5cf6; background: #f5f3ff; }\n.grade-C { color: #06b6d4; background: #ecfeff; }\n.grade-D { color: #10b981; background: #ecfdf5; }\n.grade-E { color: #94a3b8; background: #f8fafc; }\n\n.slot-name {\n  font-size: 13px;\n  font-weight: 700;\n  color: #374151;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.slot-effects {\n  display: flex;\n  gap: 12px;\n}\n\n.effect-plus {\n  display: flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 11px;\n  font-weight: 600;\n  color: #10b981;\n}\n\n.effect-minus {\n  display: flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 11px;\n  font-weight: 600;\n  color: #ef4444;\n}\n\n.slot-empty {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  color: #d1d5db;\n  font-size: 12px;\n}\n\n/* 拆卸按钮 */\n.uninstall-btn {\n  width: 28px;\n  height: 28px;\n  border-radius: 6px;\n  border: 1px solid #fecaca;\n  background: #fff;\n  color: #ef4444;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  flex-shrink: 0;\n  transition: all 0.2s;\n}\n\n.uninstall-btn:hover {\n  background: #fef2f2;\n  border-color: #ef4444;\n}\n\n/* ─── 内联仓库 ─── */\n.inline-warehouse {\n  background: #f8f9ff;\n  border: 1px solid #c7d2fe;\n  border-radius: 8px;\n  padding: 10px;\n  margin-top: -4px;\n  overflow: hidden;\n}\n\n.iw-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  font-weight: 700;\n  color: #4338ca;\n  margin-bottom: 8px;\n  padding-bottom: 6px;\n  border-bottom: 1px solid #e0e7ff;\n}\n\n.iw-close {\n  margin-left: auto;\n  width: 22px;\n  height: 22px;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: #94a3b8;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.15s;\n}\n\n.iw-close:hover {\n  background: #e0e7ff;\n  color: #4338ca;\n}\n\n.iw-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 14px;\n  color: #cbd5e1;\n  font-size: 12px;\n}\n\n.iw-list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  max-height: 180px;\n  overflow-y: auto;\n}\n\n.iw-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  background: #fff;\n  border: 1px solid #e8ecf1;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.15s;\n  user-select: none;\n}\n\n.iw-item:hover {\n  background: #eef2ff;\n  border-color: #6366f1;\n}\n\n.iw-item:active {\n  transform: scale(0.98);\n}\n\n.iw-item-grade {\n  width: 24px;\n  height: 24px;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 900;\n  font-family: 'Rajdhani', monospace;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.iw-item-info {\n  flex: 1;\n  min-width: 0;\n}\n\n.iw-item-name {\n  font-size: 12px;\n  font-weight: 700;\n  color: #374151;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.iw-item-effect {\n  display: flex;\n  gap: 8px;\n  font-size: 10px;\n}\n\n.effect-plus-sm {\n  color: #10b981;\n  font-weight: 600;\n}\n\n.effect-minus-sm {\n  color: #ef4444;\n  font-weight: 600;\n}\n\n.iw-item-action {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  opacity: 0.4;\n  transition: opacity 0.15s;\n}\n\n.iw-item:hover .iw-item-action {\n  opacity: 1;\n}\n\n/* 展开动画 */\n.slide-enter-active,\n.slide-leave-active {\n  transition: all 0.25s ease;\n  max-height: 300px;\n  opacity: 1;\n}\n\n.slide-enter-from,\n.slide-leave-to {\n  max-height: 0;\n  opacity: 0;\n  padding-top: 0;\n  padding-bottom: 0;\n  margin-top: 0;\n}\n\n/* ─── 提示 ─── */\n.mod-notice {\n  display: flex;\n  gap: 6px;\n  padding: 8px 10px;\n  background: #fffbeb;\n  border: 1px solid #fef3c7;\n  border-radius: 6px;\n  margin-bottom: 14px;\n}\n\n.mod-notice span {\n  font-size: 11px;\n  color: #92400e;\n  line-height: 1.5;\n}\n\n.mod-notice svg {\n  flex-shrink: 0;\n  margin-top: 1px;\n}\n\n/* ─── 最终五维 ─── */\n.final-stats-section {\n  margin-bottom: 14px;\n  background: #fafaff;\n  border: 1px solid #e8ecf1;\n  border-radius: 8px;\n  padding: 12px;\n}\n\n.stats-hint {\n  font-weight: 400;\n  font-size: 10px;\n  color: #94a3b8;\n  margin-left: auto;\n}\n\n.stats-grid {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.stat-row {\n  display: grid;\n  grid-template-columns: 80px 1fr;\n  grid-template-rows: auto auto;\n  gap: 2px 10px;\n  align-items: center;\n}\n\n.stat-dim {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 12px;\n  font-weight: 600;\n  color: #374151;\n  grid-row: 1 / 3;\n}\n\n.stat-abbr {\n  font-size: 9px;\n  font-weight: 800;\n  font-family: 'Rajdhani', monospace;\n  color: #6366f1;\n  background: #eef2ff;\n  padding: 1px 4px;\n  border-radius: 3px;\n  letter-spacing: 0.5px;\n}\n\n.stat-values {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-family: 'Rajdhani', monospace;\n}\n\n.stat-base {\n  font-size: 13px;\n  font-weight: 600;\n  color: #64748b;\n}\n\n.stat-arrow {\n  color: #94a3b8;\n  flex-shrink: 0;\n}\n\n.stat-eq {\n  font-size: 11px;\n  color: #cbd5e1;\n}\n\n.stat-final {\n  font-size: 15px;\n  font-weight: 800;\n  color: #374151;\n}\n\n.stat-final.val-up {\n  color: #059669;\n}\n\n.stat-final.val-down {\n  color: #dc2626;\n}\n\n.stat-diff {\n  font-size: 11px;\n  font-weight: 700;\n  padding: 0 4px;\n  border-radius: 3px;\n}\n\n.diff-up {\n  color: #059669;\n  background: #ecfdf5;\n}\n\n.diff-down {\n  color: #dc2626;\n  background: #fef2f2;\n}\n\n/* 进度条 */\n.stat-bar-track {\n  grid-colum